#include "postquantiquecoin/mining/Miner.h"
#include "postquantiquecoin/blockchain/Difficulty.h"
#include "postquantiquecoin/blockchain/MerkleTree.h"
#include "postquantiquecoin/crypto/Address.h"
#include <chrono>
#include <iostream>
namespace pqc { Miner::Miner(Blockchain& c):chain_(c){} void Miner::AddCoinbaseTransaction(Block& b,const std::string& addr,uint64_t reward){ Transaction cb; cb.timestamp=static_cast<uint64_t>(std::chrono::duration_cast<std::chrono::seconds>(std::chrono::system_clock::now().time_since_epoch()).count()); cb.inputs.push_back({std::string(64,'0'),UINT32_MAX,{'P','Q','C'},{} }); cb.outputs.push_back({reward,addr,"PQC_PUBKEY_HASH"}); cb.txid=cb.ComputeTxId(); b.transactions.insert(b.transactions.begin(),cb); } uint64_t Miner::SelectMempoolTransactions(Block& b){ auto txs=chain_.GetMempool().GetTransactionsForBlock(1000,3000000); for(const auto& tx:txs) b.transactions.push_back(tx); return chain_.GetMempool().GetTotalFeesEstimate(); } Result<MiningJob> Miner::BuildCandidateBlock(const std::string& addr){ if(!Address::Validate(addr)) return Result<MiningJob>::Err("invalid miner address"); MiningJob j; j.minerAddress=addr; j.params=chain_.Params(); j.height=chain_.GetHeight()+1; j.subsidyAtoms=chain_.GetNextSubsidy(); j.bits=chain_.Params().initialBits; j.candidateBlock.header.previousHash=chain_.GetTipHash(); j.candidateBlock.header.height=j.height; j.candidateBlock.header.bits=j.bits; j.candidateBlock.header.timestamp=static_cast<uint64_t>(std::chrono::duration_cast<std::chrono::seconds>(std::chrono::system_clock::now().time_since_epoch()).count()); j.feesAtoms=SelectMempoolTransactions(j.candidateBlock); AddCoinbaseTransaction(j.candidateBlock,addr,j.subsidyAtoms+j.feesAtoms); j.candidateBlock.header.merkleRoot=MerkleTree::ComputeRoot(j.candidateBlock.transactions); return Result<MiningJob>::Ok(j); } Result<Block> Miner::MineNextBlock(const std::string& addr,uint32_t threads){ auto j=BuildCandidateBlock(addr); if(j.IsErr()) return Result<Block>::Err(j.Error()); auto b=engine_.Mine(j.Value(),threads); if(b.IsErr()) return b; auto s=SubmitBlock(b.Value()); if(s.IsErr()) return Result<Block>::Err(s.Error()); std::cout<<"mined block "<<b.Value().GetHash()<<'\n'; return b; } Result<void> Miner::SubmitBlock(const Block& b){ return chain_.AddBlock(b); } void Miner::StartLoop(const std::string& a,uint32_t t){ stop_=false; while(!stop_) { auto r=MineNextBlock(a,t); if(r.IsErr()) std::cout<<"mining error: "<<r.Error()<<'\n'; } } void Miner::Stop(){ stop_=true; engine_.Stop(); } }
